def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return
    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65

    # Determine desired horizontal direction based on target x range
    if pos.x < target_x_min:
        desired_h_dir = 1  # Move right
    elif pos.x > target_x_max:
        desired_h_dir = -1  # Move left
    else:
        desired_h_dir = 0  # No horizontal force needed

    # Horizontal control: Pump towards target x range
    if desired_h_dir == 1:
        # Desired direction is right
        if vx > 0:
            force_x = 42.0  # Max force to increase speed toward target
        else:
            force_x = -vx * 10.0  # Counteract velocity to gain momentum
    elif desired_h_dir == -1:
        # Desired direction is left
        if vx < 0:
            force_x = -42.0  # Max force to increase speed toward target
        else:
            force_x = -vx * 10.0  # Counteract velocity to gain momentum
    else:
        force_x = 0.0

    # Dead zone suppression handling
    if abs(vx) < 0.5:
        # Apply impulse to break dead zone
        if desired_h_dir == 1:
            impulse_x = 4.2  # Rightward impulse
        elif desired_h_dir == -1:
            impulse_x = -4.2  # Leftward impulse
        else:
            impulse_x = 0.0
        sandbox.apply_impulse_to_seat(impulse_x, 0)
    else:
        # Apply clamped horizontal force
        force_x_clamped = min(max(force_x, -42.0), 42.0)
        sandbox.apply_force_to_seat(force_x_clamped, 0)

    # Vertical control: Pump to reach apex
    if pos.y < target_y:
        # Apply upward force to increase height
        force_y = 42.0  # Max vertical force to counteract gravity and wind
    else:
        # Apply downward force to decelerate for controlled landing
        force_y = -vy * 10.0

    # Clamp vertical force to pump force limit
    force_y_clamped = min(max(force_y, -42.0), 42.0)
    sandbox.apply_force_to_seat(0, force_y_clamped)
